import type { DeliveryFreezeBatch, DeviceEntity, ProtocolType, SpatialTree, SystemConnection, UserSession } from '@pacom/contracts';
import { E7F_IDS, type PacomDataAdapter } from '../../adapters';

type DeployTab = 'floorplan' | 'topology' | 'connections' | 'delivery';

export async function mountDeploymentView(
  root: HTMLElement,
  adapter: PacomDataAdapter,
  session: UserSession
): Promise<void> {
  let tab: DeployTab = 'floorplan';
  let tree: SpatialTree = await adapter.getSpatialTree();
  let devices: DeviceEntity[] = [];
  let connections: SystemConnection[] = [];
  let deliveries: DeliveryFreezeBatch[] = [];
  let selectedId: string | null = null;
  let placingMode = false;
  let copiedEndpointId: string | null = null;
  let notice = '';
  let errorMsg = '';

  async function refresh(): Promise<void> {
    errorMsg = '';
    const [t, devs, conns, dlvs] = await Promise.all([
      adapter.getSpatialTree(),
      adapter.getFloorDevices(E7F_IDS.floorId).catch(() => []),
      adapter.listConnections(E7F_IDS.projectId),
      adapter.listDeliveryBatches(E7F_IDS.floorId),
    ]);
    tree = t;
    devices = devs;
    connections = conns;
    deliveries = dlvs;
    if (!devices.some((d) => d.id === selectedId)) selectedId = devices[0]?.id ?? null;
    render();
  }

  function render(): void {
    const selected = devices.find((d) => d.id === selectedId) ?? null;
    const canEdit = session.scope.canEditDeployment;
    const totalCollected = connections.reduce((sum, c) => sum + c.collectedPoints, 0);
    const totalCalculated = connections.reduce((sum, c) => sum + c.calculatedPoints, 0);
    const connectedCount = connections.filter((c) => c.status === 'connected').length;

    root.innerHTML = `
      <div class="pacom-shell">
        <header class="pacom-header">
          <div class="pacom-header-top">
            <h1 class="pacom-title">系统部署</h1>
            <div class="pacom-header-meta">
              <span class="pacom-badge ${canEdit ? 'pacom-badge--online' : 'pacom-badge--warning'}">
                ${canEdit ? '可编辑部署与硬件绑定' : '只读权限（写入将被服务端 403 拦截）'}
              </span>
            </div>
          </div>
          <div class="pacom-header-toolbar">
            <div class="pacom-tabs" role="tablist">
              <button class="pacom-tab" role="tab" aria-selected="${tab === 'floorplan'}" data-dtab="floorplan">图纸标点与四态绑定</button>
              <button class="pacom-tab" role="tab" aria-selected="${tab === 'topology'}" data-dtab="topology">项目空间拓扑</button>
              <button class="pacom-tab" role="tab" aria-selected="${tab === 'connections'}" data-dtab="connections">系统接入（${connections.length}）</button>
              <button class="pacom-tab" role="tab" aria-selected="${tab === 'delivery'}" data-dtab="delivery">交付冻结（${deliveries.length}）</button>
            </div>
          </div>
        </header>

        ${notice ? `<div class="lov-banner lov-banner--ok"><span class="lov-banner-title">${notice}</span></div>` : ''}
        ${errorMsg ? `<div class="pacom-alert-banner">${errorMsg}</div>` : ''}

        ${
          tab === 'floorplan'
            ? `
            <section class="pacom-split">
              <aside class="pacom-left-pane" style="--pacom-sidebar-width:380px;">
                <div class="pacom-pane-toolbar">
                  <div style="font-weight:500;">E7F 设备与四态配置（${devices.length}）</div>
                  <div class="pacom-row-sub">
                    图上放点仅更新 <code>planPoint</code>，绝不自动改写物理安装态或硬件端口绑定。
                  </div>
                </div>
                <div class="pacom-list">
                  ${devices
                    .map(
                      (d) => `
                      <div class="pacom-row ${d.id === selectedId ? 'is-selected' : ''}" data-pick-dev="${d.id}">
                        <div style="min-width:0;">
                          <div class="pacom-row-title">${d.name}</div>
                          <div class="pacom-row-sub">v${d.version} · ${d.hardwareBinding?.protocol.toUpperCase() ?? '未绑定'} · ${d.physicalInstalled ? '现场已确认' : '待物理复核'}</div>
                        </div>
                        <span class="pacom-badge ${d.physicalInstalled ? 'pacom-badge--online' : 'pacom-badge--warning'}">
                          ${d.planPoint ? `${Math.round(d.planPoint.x * 100)}%,${Math.round(d.planPoint.y * 100)}%` : '未标点'}
                        </span>
                      </div>`
                    )
                    .join('')}
                </div>
                ${
                  selected
                    ? `
                    <form data-role="binding-form" style="padding:14px 16px; border-top:var(--hw) solid var(--pacom-border-subtle); background:var(--pacom-surface-primary); display:flex; flex-direction:column; gap:10px;">
                      <div style="display:flex; justify-content:space-between; align-items:center;">
                        <span style="font-weight:500; font-size:13px;">显式硬件绑定与现场复核</span>
                        <span class="pacom-badge pacom-badge--neutral">${selected.id}</span>
                      </div>
                      <div style="display:grid; grid-template-columns:1fr 1fr; gap:8px;">
                        <select class="pacom-select" name="protocol">
                          ${(['bacnet_ip', 'modbus_tcp', 'modbus_rtu', 'knx', 'mqtt', 'dali'] as ProtocolType[])
                            .map((p) => `<option value="${p}" ${selected.hardwareBinding?.protocol === p ? 'selected' : ''}>${p.toUpperCase()}</option>`)
                            .join('')}
                        </select>
                        <input class="pacom-input" name="networkAddress" placeholder="网络地址/主题" value="${selected.hardwareBinding?.networkAddress ?? ''}" />
                      </div>
                      <div style="display:grid; grid-template-columns:1fr auto; gap:8px; align-items:center;">
                        <input class="pacom-input" name="portOrChannel" placeholder="端口/回路" value="${selected.hardwareBinding?.portOrChannel ?? ''}" />
                        <label style="display:inline-flex; align-items:center; gap:6px; font-size:12px; cursor:pointer;">
                          <input type="checkbox" name="physicalInstalled" ${selected.physicalInstalled ? 'checked' : ''} />
                          现场物理已复核
                        </label>
                      </div>
                      <div style="display:flex; gap:8px; flex-wrap:wrap;">
                        <button class="pacom-btn" type="button" data-toggle-place="1">${placingMode ? '取消点图更新' : '点图更新坐标'}</button>
                        <button class="pacom-btn" type="button" data-ftt-test="1" title="远程验证指令下发、状态回读并自动恢复工况">单机回读自检</button>
                        <button class="pacom-btn pacom-btn--primary" type="submit" style="flex:1;">保存硬件绑定（v${selected.version}）</button>
                      </div>
                    </form>`
                    : ''
                }
              </aside>
              <div class="pacom-splitter"></div>
              <main class="pacom-right-pane">
                <div class="pacom-canvas-stage" data-role="deploy-stage" style="cursor:${placingMode ? 'crosshair' : 'default'};">
                  <div class="pacom-canvas-viewport">
                    <div class="pacom-plan-wrap" data-role="deploy-plan">
                      <img class="pacom-plan-img" src="./media/7F.webp" alt="E7F 部署平面图" />
                      ${devices
                        .filter((d) => d.planPoint)
                        .map(
                          (d) => `
                          <button class="pacom-pin ${d.id === selectedId ? 'is-selected' : ''} ${d.connectivity === 'offline' ? 'pacom-pin--offline' : ''}"
                            style="left:${(d.planPoint!.x * 100).toFixed(2)}%; top:${(d.planPoint!.y * 100).toFixed(2)}%;"
                            data-pick-dev="${d.id}">
                            <span>${d.name.slice(0, 7)}</span>
                          </button>`
                        )
                        .join('')}
                    </div>
                  </div>
                  ${
                    placingMode && selected
                      ? `<div style="position:absolute; top:16px; left:16px; z-index:8;" class="pacom-badge pacom-badge--accent">标点模式：点击图纸任意位置更新「${selected.name}」的 2D 坐标（不改动硬件绑定）</div>`
                      : ''
                  }
                </div>
              </main>
            </section>`
            : tab === 'topology'
              ? `
              <div class="pacom-content-page" style="padding:4px 0 24px;">
                <section class="lov-section">
                  <div class="lov-section-head">
                    <h2 class="lov-section-title">项目 → 楼宇 → 楼层归属拓扑</h2>
                    <span class="pacom-row-sub">共 ${tree.projects.length} 个项目 · ${tree.buildings.length} 栋楼宇</span>
                  </div>
                  <div style="display:grid; grid-template-columns:repeat(auto-fill,minmax(300px,1fr)); gap:14px;">
                    ${tree.projects
                      .map((p) => {
                        const blds = tree.buildings.filter((b) => b.projectId === p.id);
                        return `
                          <div class="pacom-card" style="padding:16px; gap:10px;">
                            <img src="${p.imageUrl ?? './media/gzlab.jpg'}" alt="${p.name}" style="width:100%; height:128px; object-fit:cover; border-radius:10px;" />
                            <div>
                              <strong style="font-size:15px; font-weight:500;">${p.name}</strong>
                              <div class="pacom-row-sub">${p.city ?? ''} ${p.address ?? ''} · ${blds.length} 栋授权楼宇</div>
                            </div>
                            <div style="display:flex; flex-direction:column; gap:6px;">
                              ${blds
                                .map(
                                  (b) => `
                                  <div class="pacom-receipt-item">
                                    <span><strong>${b.name}</strong> · 地上 ${b.aboveFloors}F / ${b.areaSqm ?? '-'} m²</span>
                                    <span class="pacom-badge ${b.id === E7F_IDS.buildingId ? 'pacom-badge--accent' : 'pacom-badge--neutral'}">${b.id === E7F_IDS.buildingId ? '含 E7F' : '对照'}</span>
                                  </div>`
                                )
                                .join('')}
                            </div>
                          </div>`;
                      })
                      .join('')}
                  </div>
                </section>
              </div>`
              : tab === 'connections'
                ? `
                <div class="pacom-content-page" style="padding:4px 0 24px;">
                  <div class="lov-kpi-strip">
                    <div class="lov-kpi-cell">
                      <span class="lov-kpi-label">已连通通道</span>
                      <div class="lov-kpi-value">${connectedCount}<span class="lov-kpi-unit">/ ${connections.length}</span></div>
                      <span class="lov-kpi-delta">边缘网关在线监控</span>
                    </div>
                    <div class="lov-kpi-cell">
                      <span class="lov-kpi-label">数据采集健康度</span>
                      <div class="lov-kpi-value">${connections.length > 0 ? Math.round((connectedCount / connections.length) * 100) : 100}<span class="lov-kpi-unit">%</span></div>
                      <span class="lov-kpi-delta">区分设备真故障与断流</span>
                    </div>
                    <div class="lov-kpi-cell">
                      <span class="lov-kpi-label">原始采集点</span>
                      <div class="lov-kpi-value">${totalCollected}<span class="lov-kpi-unit">点</span></div>
                      <span class="lov-kpi-delta">协议直采实时遥测</span>
                    </div>
                    <div class="lov-kpi-cell">
                      <span class="lov-kpi-label">衍生计算点</span>
                      <div class="lov-kpi-value">${totalCalculated}<span class="lov-kpi-unit">点</span></div>
                      <span class="lov-kpi-delta">能碳与聚合虚拟点位</span>
                    </div>
                  </div>

                  <section class="lov-section">
                    <div class="lov-section-head">
                      <h2 class="lov-section-title">边缘网关与协议接入清单</h2>
                      <span class="pacom-row-sub">采集点与计算点独立计数</span>
                    </div>
                    <div class="lov-table-card">
                      <div class="lov-table-wrap">
                        <table class="lov-table">
                          <thead>
                            <tr>
                              <th>通道名称</th>
                              <th>协议</th>
                              <th>接入端点</th>
                              <th>点位规模</th>
                              <th>连通状态</th>
                              <th style="text-align:right;">操作</th>
                            </tr>
                          </thead>
                          <tbody>
                            ${connections
                              .map(
                                (c) => `
                                <tr>
                                  <td><strong>${c.name}</strong></td>
                                  <td><span class="pacom-badge pacom-badge--neutral">${c.protocol.toUpperCase()}</span></td>
                                  <td><code style="font-size:12px;">${c.endpoint}</code></td>
                                  <td>采集 ${c.collectedPoints} / 计算 ${c.calculatedPoints}</td>
                                  <td>
                                    <span class="pacom-badge ${c.status === 'connected' ? 'pacom-badge--online' : 'pacom-badge--warning'}">
                                      ${c.status === 'connected' ? '已连通' : c.status}
                                    </span>
                                  </td>
                                  <td style="text-align:right;">
                                    <button class="pacom-btn pacom-btn--ghost" data-copy-endpoint="${c.id}" data-endpoint-val="${c.endpoint}">
                                      ${copiedEndpointId === c.id ? '已复制' : '复制端点'}
                                    </button>
                                  </td>
                                </tr>`
                              )
                              .join('')}
                          </tbody>
                        </table>
                      </div>
                    </div>
                  </section>
                </div>`
                : `
                <div class="pacom-content-page" style="padding:4px 0 24px;">
                  <section class="lov-section">
                    <div class="lov-section-head">
                      <h2 class="lov-section-title">E7F 交付冻结批次</h2>
                      <button class="pacom-btn pacom-btn--primary" data-freeze-batch="1" ${!canEdit ? 'disabled' : ''}>+ 新建交付冻结快照</button>
                    </div>
                    <div class="lov-table-card">
                      <div class="lov-table-wrap">
                        <table class="lov-table">
                          <thead>
                            <tr>
                              <th>版本标签</th>
                              <th>现场核验进度</th>
                              <th>冻结人与备注</th>
                              <th>状态</th>
                            </tr>
                          </thead>
                          <tbody>
                            ${deliveries
                              .map(
                                (b) => `
                                <tr>
                                  <td>
                                    <div style="font-weight:500;">${b.versionTag}</div>
                                    <div class="pacom-row-sub"><code>${b.id}</code></div>
                                  </td>
                                  <td><strong>${b.verifiedCount}</strong> / ${b.deviceCount} 台设备</td>
                                  <td>
                                    <div>${b.frozenBy}</div>
                                    <div class="pacom-row-sub">${b.note ?? '-'}</div>
                                  </td>
                                  <td><span class="pacom-badge pacom-badge--accent">${b.status}</span></td>
                                </tr>`
                              )
                              .join('')}
                          </tbody>
                        </table>
                      </div>
                    </div>
                  </section>
                </div>`
        }
      </div>
    `;

    root.querySelectorAll<HTMLButtonElement>('[data-dtab]').forEach((btn) => {
      btn.addEventListener('click', () => {
        tab = btn.dataset.dtab as DeployTab;
        notice = '';
        errorMsg = '';
        render();
      });
    });

    root.querySelectorAll<HTMLElement>('[data-pick-dev]').forEach((el) => {
      el.addEventListener('click', () => {
        selectedId = el.dataset.pickDev ?? null;
        render();
      });
    });

    root.querySelector<HTMLButtonElement>('[data-toggle-place]')?.addEventListener('click', () => {
      placingMode = !placingMode;
      render();
    });

    root.querySelector<HTMLButtonElement>('[data-ftt-test]')?.addEventListener('click', () => {
      if (!selected) return;
      errorMsg = '';
      if (selected.connectivity === 'offline') {
        errorMsg = `单机回读自检未通过：「${selected.name}」当前离线，请先检查网关 ${selected.hardwareBinding?.networkAddress ?? '-'} 通信状态。`;
      } else {
        notice = `单机回读自检通过（PASS）：「${selected.name}」指令下发 → 状态回读一致 → 已安全自动恢复原工况。`;
      }
      render();
    });

    root.querySelectorAll<HTMLButtonElement>('[data-copy-endpoint]').forEach((btn) => {
      btn.addEventListener('click', async () => {
        const val = btn.dataset.endpointVal ?? '';
        const id = btn.dataset.copyEndpoint ?? null;
        try {
          await navigator.clipboard.writeText(val);
          copiedEndpointId = id;
          render();
          window.setTimeout(() => {
            copiedEndpointId = null;
            render();
          }, 1600);
        } catch {
          // 忽略剪贴板权限限制
        }
      });
    });

    root.querySelector<HTMLElement>('[data-role="deploy-plan"]')?.addEventListener('click', async (e) => {
      if (!placingMode || !selected) return;
      const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
      const x = Math.max(0.02, Math.min(0.98, (e.clientX - rect.left) / rect.width));
      const y = Math.max(0.02, Math.min(0.98, (e.clientY - rect.top) / rect.height));
      try {
        await adapter.updateDevicePlanPoint({
          deviceId: selected.id,
          floorId: E7F_IDS.floorId,
          planVersion: selected.planPoint?.planVersion ?? 1,
          x,
          y,
          expectedVersion: selected.version,
        });
        placingMode = false;
        notice = `已更新「${selected.name}」图上坐标（硬件绑定与物理安装态保持不变）`;
        await refresh();
      } catch (err) {
        errorMsg = err instanceof Error ? err.message : String(err);
        render();
      }
    });

    root.querySelector<HTMLFormElement>('[data-role="binding-form"]')?.addEventListener('submit', async (e) => {
      e.preventDefault();
      if (!selected) return;
      const fd = new FormData(e.currentTarget as HTMLFormElement);
      try {
        await adapter.updateDeviceHardwareBinding({
          deviceId: selected.id,
          gatewayId: selected.hardwareBinding?.gatewayId ?? 'dev-e7f-gw-01',
          protocol: String(fd.get('protocol')) as ProtocolType,
          networkAddress: String(fd.get('networkAddress') ?? ''),
          portOrChannel: String(fd.get('portOrChannel') ?? ''),
          physicalInstalled: fd.get('physicalInstalled') === 'on',
          expectedVersion: selected.version,
        });
        notice = `已保存「${selected.name}」的硬件绑定与物理安装状态`;
        await refresh();
      } catch (err) {
        errorMsg = err instanceof Error ? err.message : String(err);
        render();
      }
    });

    root.querySelector<HTMLButtonElement>('[data-freeze-batch]')?.addEventListener('click', async () => {
      try {
        const created = await adapter.freezeDeliveryBatch(E7F_IDS.floorId, '前端系统部署发起冻结');
        notice = `已生成冻结批次 ${created.versionTag}（核验 ${created.verifiedCount}/${created.deviceCount}）`;
        await refresh();
      } catch (err) {
        errorMsg = err instanceof Error ? err.message : String(err);
        render();
      }
    });
  }

  await refresh();
}
