import type { AnalysisCategory, AnalysisRange, AnalysisReport, UserSession } from '@pacom/contracts';
import { E7F_IDS, type PacomDataAdapter } from '../../adapters';

const CATEGORY_META: Array<{ id: AnalysisCategory; label: string; desc: string }> = [
  { id: 'energy', label: '能源', desc: '分项能耗与峰谷负荷趋势' },
  { id: 'environment', label: '环境', desc: '温湿度、CO₂ 与洁净室舒适度' },
  { id: 'occupancy', label: '占用', desc: '工位与会议室空间利用率' },
  { id: 'health', label: '设备健康', desc: '在线率、通信延迟与异常分布' },
  { id: 'carbon', label: '碳排放', desc: '等效碳排强度与节能基线对比' },
];

function renderSvgChart(report: AnalysisReport): string {
  const maxVal = Math.max(...report.series.map((s) => Math.max(s.value, s.baseline ?? 0)), 1);
  const barW = 42;
  const gap = 26;
  const padL = 32;
  const chartW = Math.max(report.series.length * (barW + gap) + padL * 2, 420);
  const chartH = 204;
  const baseY = 164;
  const plotH = 128;

  const gridLines = [0, 0.25, 0.5, 0.75, 1]
    .map((ratio) => {
      const y = Math.round(baseY - ratio * plotH);
      return `<line x1="${padL - 8}" y1="${y}" x2="${chartW - 16}" y2="${y}" stroke="oklch(85.12% 0 107 / 0.55)" stroke-dasharray="${ratio === 0 ? '0' : '3 3'}" />`;
    })
    .join('');

  // Willow Fault Occurrence Shading：超出基线 8% 以上的时段叠加浅红提示阴影
  const bars = report.series
    .map((pt, i) => {
      const x = padL + i * (barW + gap);
      const h = Math.max(6, Math.round((pt.value / maxVal) * plotH));
      const y = baseY - h;
      const isOverBaseline = typeof pt.baseline === 'number' && pt.value > pt.baseline * 1.08;
      const faultShade = isOverBaseline
        ? `<rect x="${x - 6}" y="28" width="${barW + 12}" height="${baseY - 28}" rx="8" fill="oklch(58.53% 0.2203 26.56 / 0.09)" />`
        : '';
      const baseLineMark =
        typeof pt.baseline === 'number'
          ? `<line x1="${x - 4}" y1="${Math.round(baseY - (pt.baseline / maxVal) * plotH)}" x2="${x + barW + 4}" y2="${Math.round(baseY - (pt.baseline / maxVal) * plotH)}" stroke="var(--pacom-brand)" stroke-width="1.5" stroke-dasharray="3 2" opacity="0.6" />`
          : '';
      return `
        ${faultShade}
        ${baseLineMark}
        <rect x="${x}" y="${y}" width="${barW}" height="${h}" rx="7" fill="${isOverBaseline ? 'var(--pacom-status-warning)' : 'var(--pacom-accent-solid)'}" opacity="0.86" />
        <text x="${x + barW / 2}" y="${y - 7}" text-anchor="middle" font-size="11" font-weight="500" fill="var(--pacom-text-primary)">${pt.value}</text>
        <text x="${x + barW / 2}" y="${baseY + 20}" text-anchor="middle" font-size="11" fill="var(--pacom-text-secondary)">${pt.label}</text>
      `;
    })
    .join('');

  return `
    <svg viewBox="0 0 ${chartW} ${chartH}" style="width:100%; height:210px; display:block;" role="img" aria-label="${report.category} 趋势图">
      ${gridLines}
      ${bars}
    </svg>
  `;
}

function downloadReportCsv(report: AnalysisReport): void {
  const lines = [
    ['时段', `数值 (${report.unit})`, `基线 (${report.unit})`].join(','),
    ...report.series.map((s) => [s.label, String(s.value), s.baseline !== undefined ? String(s.baseline) : ''].join(',')),
  ];
  const blob = new Blob([`\uFEFF${lines.join('\n')}`], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `pacom-${report.category}-${report.range}.csv`;
  a.click();
  URL.revokeObjectURL(url);
}

export async function mountAnalysisView(
  root: HTMLElement,
  adapter: PacomDataAdapter,
  _session: UserSession
): Promise<void> {
  let category: AnalysisCategory = 'energy';
  let range: AnalysisRange = '7d';
  let chartMode: 'chart' | 'table' = 'chart';
  let showCanvas = false;
  let report: AnalysisReport | null = null;

  async function load(): Promise<void> {
    report = await adapter.getAnalysisReport(category, range, E7F_IDS.floorId);
    render();
  }

  function render(): void {
    if (!report) return;
    const activeCat = CATEGORY_META.find((c) => c.id === category) ?? CATEGORY_META[0];
    const warningZones = report.zoneBreakdown.filter((z) => z.status === 'warning');

    root.innerHTML = `
      <div class="pacom-shell">
        <header class="pacom-header">
          <div class="pacom-header-top">
            <h1 class="pacom-title">数据分析</h1>
            <div class="pacom-header-meta">
              <span class="pacom-badge pacom-badge--online">数据完整度 99.4%</span>
              <span class="pacom-badge pacom-badge--neutral">${report.scopeLabel}</span>
              <select class="pacom-select" data-range-select aria-label="统计时间范围">
                <option value="today" ${range === 'today' ? 'selected' : ''}>今日</option>
                <option value="7d" ${range === '7d' ? 'selected' : ''}>近 7 天</option>
                <option value="30d" ${range === '30d' ? 'selected' : ''}>近 30 天</option>
              </select>
              <button class="pacom-btn" data-export-csv="1">导出 CSV</button>
              <button class="pacom-btn" data-toggle-canvas="1">${showCanvas ? '收起空间画布' : '展开楼层对照'}</button>
            </div>
          </div>
        </header>

        <div class="lov-subnav-layout">
          <nav class="lov-subnav-rail" aria-label="分析维度">
            <div class="lov-subnav-group">
              <div class="lov-subnav-group-title">分析维度</div>
              ${CATEGORY_META.map(
                (c) => `
                  <button class="lov-subnav-item" aria-current="${category === c.id ? 'true' : 'false'}" data-cat="${c.id}">
                    <span>${c.label}</span>
                  </button>`
              ).join('')}
            </div>
          </nav>

          <div class="lov-subnav-main">
            <div class="lov-kpi-strip" role="region" aria-label="核心统计指标">
              ${report.kpis
                .map(
                  (k) => `
                  <div class="lov-kpi-cell">
                    <span class="lov-kpi-label">${k.label}</span>
                    <div class="lov-kpi-value">
                      <span>${k.value}</span>
                      ${k.unit ? `<span class="lov-kpi-unit">${k.unit}</span>` : ''}
                    </div>
                    <span class="lov-kpi-delta">${k.delta ?? '与基线持平'}</span>
                  </div>`
                )
                .join('')}
            </div>

            <section class="lov-section">
              <div class="lov-section-head">
                <h2 class="lov-section-title">${activeCat?.label ?? '趋势'}统计（${report.unit}）</h2>
                <div style="display:flex; align-items:center; gap:10px;">
                  <span class="pacom-row-sub">虚线为目标基线 · 浅红阴影为超基线异常段</span>
                  <div class="pacom-tabs">
                    <button class="pacom-tab" aria-selected="${chartMode === 'chart'}" data-chart-mode="chart">趋势图</button>
                    <button class="pacom-tab" aria-selected="${chartMode === 'table'}" data-chart-mode="table">明细原表</button>
                  </div>
                </div>
              </div>
              <div class="pacom-card" style="gap:16px;">
                ${
                  chartMode === 'chart'
                    ? renderSvgChart(report)
                    : `
                    <div class="lov-table-wrap">
                      <table class="lov-table">
                        <thead>
                          <tr>
                            <th>统计时段</th>
                            <th>实测值（${report.unit}）</th>
                            <th>基线参考</th>
                            <th>状态</th>
                          </tr>
                        </thead>
                        <tbody>
                          ${report.series
                            .map((s) => {
                              const over = typeof s.baseline === 'number' && s.value > s.baseline * 1.08;
                              return `
                                <tr>
                                  <td><strong>${s.label}</strong></td>
                                  <td>${s.value}</td>
                                  <td>${s.baseline ?? '-'}</td>
                                  <td><span class="pacom-badge ${over ? 'pacom-badge--warning' : 'pacom-badge--online'}">${over ? '超基线' : '正常'}</span></td>
                                </tr>`;
                            })
                            .join('')}
                        </tbody>
                      </table>
                    </div>`
                }
                <div class="lov-banner">
                  <div class="lov-banner-text">
                    <span class="lov-banner-title">${activeCat?.desc ?? '空间运行洞察'}</span>
                    <span class="lov-banner-sub">
                      ${
                        warningZones.length > 0
                          ? `当前有 ${warningZones.length} 个功能区指标偏高（${warningZones.map((z) => z.zoneName).join('、')}），建议结合楼层平面图核查设备策略。`
                          : '当前统计周期内各功能区运行平稳，均在目标基线区间内。'
                      }
                    </span>
                  </div>
                  <button class="pacom-btn" data-toggle-canvas="1">${showCanvas ? '隐藏平面图' : '对照 E7F 平面图'}</button>
                </div>
              </div>
            </section>

            <div class="lov-grid-2">
              <section class="lov-section">
                <div class="lov-section-head">
                  <h2 class="lov-section-title">功能区明细对比</h2>
                  <span class="pacom-row-sub">${report.zoneBreakdown.length} 个分区</span>
                </div>
                <div class="lov-table-card">
                  <div class="lov-table-wrap">
                    <table class="lov-table">
                      <thead>
                        <tr>
                          <th>功能区</th>
                          <th>当前值</th>
                          <th>状态</th>
                        </tr>
                      </thead>
                      <tbody>
                        ${report.zoneBreakdown
                          .map(
                            (z) => `
                            <tr>
                              <td>
                                <div style="font-weight:500;">${z.zoneName}</div>
                                <div class="pacom-row-sub">${z.zoneId}</div>
                              </td>
                              <td><strong>${z.value}</strong> <span class="pacom-row-sub">${z.unit}</span></td>
                              <td>
                                <span class="pacom-badge ${z.status === 'warning' ? 'pacom-badge--warning' : 'pacom-badge--online'}">
                                  ${z.status === 'warning' ? '偏高关注' : '正常'}
                                </span>
                              </td>
                            </tr>`
                          )
                          .join('')}
                      </tbody>
                    </table>
                  </div>
                </div>
              </section>

              <section class="lov-section">
                <div class="lov-section-head">
                  <h2 class="lov-section-title">空间对照预览</h2>
                  <span class="pacom-row-sub">与首页控制状态独立</span>
                </div>
                <div class="pacom-card" style="flex:1; justify-content:center; align-items:center; min-height:220px;">
                  ${
                    showCanvas
                      ? `<img class="pacom-plan-img" src="./media/7F.webp" alt="E7F 分析楼层预览" style="max-height:240px;" />`
                      : `
                        <div class="lov-empty-state" style="padding:24px 12px;">
                          <strong>按需开启 E7F 空间对照</strong>
                          <span>点击右上角或下方按钮可在当前分析视图中叠加 E7F 楼层平面图。</span>
                          <button class="pacom-btn" style="margin-top:8px;" data-toggle-canvas="1">展开 E7F 平面图</button>
                        </div>`
                  }
                </div>
              </section>
            </div>
          </div>
        </div>
      </div>
    `;

    root.querySelectorAll<HTMLButtonElement>('[data-cat]').forEach((btn) => {
      btn.addEventListener('click', () => {
        category = btn.dataset.cat as AnalysisCategory;
        void load();
      });
    });

    root.querySelector<HTMLSelectElement>('[data-range-select]')?.addEventListener('change', (e) => {
      range = (e.currentTarget as HTMLSelectElement).value as AnalysisRange;
      void load();
    });

    root.querySelectorAll<HTMLButtonElement>('[data-chart-mode]').forEach((btn) => {
      btn.addEventListener('click', () => {
        chartMode = (btn.dataset.chartMode as 'chart' | 'table') ?? 'chart';
        render();
      });
    });

    root.querySelector<HTMLButtonElement>('[data-export-csv]')?.addEventListener('click', () => {
      if (report) downloadReportCsv(report);
    });

    root.querySelectorAll<HTMLButtonElement>('[data-toggle-canvas]').forEach((btn) => {
      btn.addEventListener('click', () => {
        showCanvas = !showCanvas;
        render();
      });
    });
  }

  await load();
}
