import { DemoAdapter } from './demo-adapter';
import { LiveApiAdapter } from './live-api-adapter';
import type { PacomDataAdapter } from './types';

export function createDataAdapter(): PacomDataAdapter {
  const mode = (import.meta.env.VITE_DATA_MODE ?? 'demo').toLowerCase();
  if (mode === 'live') {
    const apiBaseUrl = import.meta.env.VITE_API_BASE_URL;
    const wsBaseUrl = import.meta.env.VITE_WS_BASE_URL;
    if (!apiBaseUrl || !wsBaseUrl) {
      throw new Error('VITE_DATA_MODE=live 时必须配置 VITE_API_BASE_URL 与 VITE_WS_BASE_URL');
    }
    return new LiveApiAdapter({ apiBaseUrl, wsBaseUrl });
  }
  return new DemoAdapter();
}

export * from './types';
export { DemoAdapter, DEMO_ROLE_PROFILES, E7F_IDS, type ContractTraceEntry } from './demo-adapter';
export { LiveApiAdapter } from './live-api-adapter';
